<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { toast } from 'vue-sonner'
import { useGroupsStore } from '@/stores/groups'
import { useWorkspaceStore } from '@/stores/workspace'
import { FolderIcon, PlusIcon, ChevronDownIcon, ChevronRightIcon, EllipsisIcon } from '@lucide/vue'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import AppTooltip from '@/components/AppTooltip.vue'
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuGroup, DropdownMenuItem } from '@/components/ui/dropdown-menu'
const props = defineProps<{ collapsed: boolean; search: string }>()
const groups = useGroupsStore(); const workspace = useWorkspaceStore(); const route = useRoute(); const router = useRouter(); const expanded = ref(true)
const visible = computed(() => groups.groups.filter(item => item.name.toLowerCase().includes(props.search.trim().toLowerCase())))
function count(id: string) { return workspace.repositories.filter(repo => groups.groups.find(item => item.id === id)?.members.includes(repo.id)).length }
async function move(id: string, offset: number) { const list = [...groups.groups]; const index = list.findIndex(item => item.id === id); const next = index + offset; if (index < 0 || next < 0 || next >= list.length) return; [list[index], list[next]] = [list[next]!, list[index]!]; try { await groups.save(list) } catch (reason) { toast.error(String(reason)) } }
</script>
<template><section class="flex min-w-0 flex-col gap-1"><div class="flex items-center justify-between px-2 py-2"><span v-if="!collapsed" class="text-sm font-medium text-muted-foreground">分组</span><div class="flex items-center gap-1"><AppTooltip v-if="!collapsed" :text="expanded ? '收起分组' : '展开分组'"><Button variant="ghost" size="icon-sm" :aria-expanded="expanded" :aria-label="expanded ? '收起分组' : '展开分组'" @click="expanded = !expanded"><ChevronDownIcon v-if="expanded" /><ChevronRightIcon v-else /></Button></AppTooltip><AppTooltip text="新建分组"><Button variant="ghost" size="icon-sm" aria-label="新建分组" :disabled="groups.saving" @click="groups.edit()"><PlusIcon /></Button></AppTooltip></div></div><p v-if="groups.error && !collapsed" class="break-all px-2 text-xs text-destructive">{{ groups.error }}</p><template v-if="expanded || collapsed"><div v-for="group in visible" :key="group.id" class="flex min-w-0 items-center gap-1"><AppTooltip :text="group.name"><Button variant="ghost" :class="['min-w-0 flex-1 justify-start',route.query.group === group.id && 'bg-secondary']" @click="router.push({path:'/',query:{group:group.id}})"><FolderIcon data-icon="inline-start" :style="/^#[0-9a-f]{6}$/i.test(group.color) ? {color:group.color} : undefined" :class="{ 'text-primary':group.color === 'primary','text-success':group.color === 'success','text-warning':group.color === 'warning','text-info':group.color === 'info','text-muted-foreground':group.color === 'muted' }" /><span v-if="!collapsed" class="truncate">{{ group.name }}</span><Badge v-if="!collapsed" variant="secondary" class="ml-auto">{{ count(group.id) }}</Badge></Button></AppTooltip><DropdownMenu v-if="!collapsed"><DropdownMenuTrigger as-child><Button variant="ghost" size="icon-sm" :aria-label="`管理分组 ${group.name}`"><EllipsisIcon /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuGroup><DropdownMenuItem @select="groups.edit(group.id)">管理仓库／重命名</DropdownMenuItem><DropdownMenuItem :disabled="groups.saving || groups.groups[0]?.id === group.id" @select="move(group.id,-1)">上移</DropdownMenuItem><DropdownMenuItem :disabled="groups.saving || groups.groups.at(-1)?.id === group.id" @select="move(group.id,1)">下移</DropdownMenuItem><DropdownMenuItem @select="groups.edit(group.id)">删除分组…</DropdownMenuItem></DropdownMenuGroup></DropdownMenuContent></DropdownMenu></div><p v-if="!visible.length && !collapsed" class="flex min-h-20 items-center justify-center px-2 py-4 text-center text-xs text-muted-foreground">{{ search ? '没有匹配分组' : '点击 ＋ 创建分组' }}</p></template></section></template>
